package com.rohit.inventory.controller;
import com.rohit.inventory.dto.response.*; import com.rohit.inventory.repository.AlertRepository; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/alerts") public class AlertController { private final AlertRepository alerts; public AlertController(AlertRepository alerts){this.alerts=alerts;} @GetMapping @PreAuthorize("hasAuthority('ALERT_READ') or hasAuthority('INVENTORY_READ')") public ApiResponse<Page<AlertResponse>> list(@RequestParam(defaultValue="ACTIVE") String status,@RequestParam(required=false) UUID warehouseId,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){Page<com.rohit.inventory.entity.Alert> result=warehouseId==null?alerts.findByStatus(status,p):alerts.findByStatusAndWarehouseId(status,warehouseId,p);return ApiResponse.success("Alerts retrieved successfully",result.map(a->new AlertResponse(a.getId(),a.getAlertType(),a.getSeverity().name(),a.getTitle(),a.getMessage(),a.getWarehouse()==null?null:a.getWarehouse().getId(),a.getProduct()==null?null:a.getProduct().getId(),a.getStatus(),a.getCreatedAt())));} }
